// Package todo holds the Todo type and an in-memory store for it.
package todo

import (
	"strings"
	"sync"
	"time"
	"unicode/utf8"

	"example.com/app/internal/clock"
	"example.com/app/internal/id"
)

// MaxTitleLen is the longest allowed title, in characters.
const MaxTitleLen = 200

// Todo is one item on the list.
type Todo struct {
	ID        string    `json:"id"`
	Title     string    `json:"title"`
	Done      bool      `json:"done"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

// Update describes a partial change. A nil field is left as it is.
type Update struct {
	Title *string
	Done  *bool
}

// ListOptions selects and pages the items List returns.
type ListOptions struct {
	// Done keeps only items with this done state when not nil.
	Done *bool
	// Limit is the most items to return. Zero or less means no limit.
	Limit int
	// Offset is the number of matching items to skip.
	Offset int
}

// Store keeps todos in memory and is safe for concurrent use.
type Store struct {
	clock clock.Clock

	mu    sync.RWMutex     // guards items and order
	items map[string]*Todo // by id
	order []string         // ids, oldest first
}

// NewStore returns an empty Store that reads time from clk.
func NewStore(clk clock.Clock) *Store {
	return &Store{clock: clk, items: make(map[string]*Todo)}
}

// ValidateTitle trims title and checks its length. It returns the trimmed
// title, or ErrInvalidTitle.
func ValidateTitle(title string) (string, error) {
	t := strings.TrimSpace(title)
	if n := utf8.RuneCountInString(t); n < 1 || n > MaxTitleLen {
		return "", ErrInvalidTitle
	}
	return t, nil
}

// Create adds a new, not done item with the given title.
func (s *Store) Create(title string) (Todo, error) {
	t, err := ValidateTitle(title)
	if err != nil {
		return Todo{}, err
	}
	now := s.clock.Now()
	item := &Todo{ID: id.New(), Title: t, CreatedAt: now, UpdatedAt: now}

	s.mu.Lock()
	defer s.mu.Unlock()
	s.items[item.ID] = item
	s.order = append(s.order, item.ID)
	return *item, nil
}

// Get returns the item with the given id, or ErrNotFound.
func (s *Store) Get(itemID string) (Todo, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	item, ok := s.items[itemID]
	if !ok {
		return Todo{}, ErrNotFound
	}
	return *item, nil
}

// Update applies u to the item with the given id and returns the result.
// It returns ErrNotFound or ErrInvalidTitle without changing anything.
func (s *Store) Update(itemID string, u Update) (Todo, error) {
	var title string
	if u.Title != nil {
		t, err := ValidateTitle(*u.Title)
		if err != nil {
			return Todo{}, err
		}
		title = t
	}
	now := s.clock.Now()

	s.mu.Lock()
	defer s.mu.Unlock()
	item, ok := s.items[itemID]
	if !ok {
		return Todo{}, ErrNotFound
	}
	if u.Title != nil {
		item.Title = title
	}
	if u.Done != nil {
		item.Done = *u.Done
	}
	item.UpdatedAt = now
	return *item, nil
}

// Delete removes the item with the given id, or returns ErrNotFound.
func (s *Store) Delete(itemID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.items[itemID]; !ok {
		return ErrNotFound
	}
	delete(s.items, itemID)
	for i, v := range s.order {
		if v == itemID {
			s.order = append(s.order[:i], s.order[i+1:]...)
			break
		}
	}
	return nil
}

// List returns matching items, newest first, after applying the offset and limit.
func (s *Store) List(opts ListOptions) []Todo {
	s.mu.RLock()
	defer s.mu.RUnlock()
	out := []Todo{}
	skip := max(opts.Offset, 0)
	for i := len(s.order) - 1; i >= 0; i-- {
		item := s.items[s.order[i]]
		if opts.Done != nil && item.Done != *opts.Done {
			continue
		}
		if skip > 0 {
			skip--
			continue
		}
		if opts.Limit > 0 && len(out) >= opts.Limit {
			break
		}
		out = append(out, *item)
	}
	return out
}
EOF
cat > internal/api/handler.go <<'EOF'
package api

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strconv"

	"example.com/app/internal/log"
	"example.com/app/internal/todo"
)

const (
	maxBodyBytes = 1 << 20
	defaultLimit = 20
	maxLimit     = 100
)

type handler struct {
	store *todo.Store
}

// NewHandler returns the HTTP handler for the todo API, backed by store.
func NewHandler(store *todo.Store) http.Handler {
	h := &handler{store: store}
	mux := http.NewServeMux()
	mux.HandleFunc("POST /todos", h.create)
	mux.HandleFunc("GET /todos", h.list)
	mux.HandleFunc("GET /todos/{id}", h.get)
	mux.HandleFunc("PATCH /todos/{id}", h.update)
	mux.HandleFunc("DELETE /todos/{id}", h.delete)
	return mux
}

type createRequest struct {
	Title string `json:"title"`
}

type updateRequest struct {
	Title *string `json:"title"`
	Done  *bool   `json:"done"`
}

// decode reads one JSON object from the body into v. On failure it writes the
// error response and returns false.
func decode(w http.ResponseWriter, r *http.Request, v any) bool {
	r.Body = http.MaxBytesReader(w, r.Body, maxBodyBytes)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	err := dec.Decode(v)
	if err == nil {
		if _, err2 := dec.Token(); err2 != io.EOF {
			err = errors.New("trailing data")
		}
	}
	if err != nil {
		var tooBig *http.MaxBytesError
		if errors.As(err, &tooBig) {
			Error(w, http.StatusRequestEntityTooLarge, "request body too large")
			return false
		}
		Error(w, http.StatusBadRequest, "request body must be a single valid JSON object with known fields")
		return false
	}
	return true
}

func (h *handler) fail(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, todo.ErrNotFound):
		Error(w, http.StatusNotFound, "todo not found")
	case errors.Is(err, todo.ErrInvalidTitle):
		Error(w, http.StatusBadRequest, "title must be 1 to 200 characters after trimming")
	default:
		log.Error("todo store", "err", err)
		Error(w, http.StatusInternalServerError, "internal error, try again later")
	}
}

func (h *handler) create(w http.ResponseWriter, r *http.Request) {
	var req createRequest
	if !decode(w, r, &req) {
		return
	}
	item, err := h.store.Create(req.Title)
	if err != nil {
		h.fail(w, err)
		return
	}
	JSON(w, http.StatusCreated, item)
}

func (h *handler) get(w http.ResponseWriter, r *http.Request) {
	item, err := h.store.Get(r.PathValue("id"))
	if err != nil {
		h.fail(w, err)
		return
	}
	JSON(w, http.StatusOK, item)
}

func (h *handler) update(w http.ResponseWriter, r *http.Request) {
	var req updateRequest
	if !decode(w, r, &req) {
		return
	}
	if req.Title == nil && req.Done == nil {
		Error(w, http.StatusBadRequest, "provide title and/or done")
		return
	}
	item, err := h.store.Update(r.PathValue("id"), todo.Update{Title: req.Title, Done: req.Done})
	if err != nil {
		h.fail(w, err)
		return
	}
	JSON(w, http.StatusOK, item)
}

func (h *handler) delete(w http.ResponseWriter, r *http.Request) {
	if err := h.store.Delete(r.PathValue("id")); err != nil {
		h.fail(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (h *handler) list(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	opts := todo.ListOptions{Limit: defaultLimit}
	if v := q.Get("done"); v != "" {
		b, err := strconv.ParseBool(v)
		if err != nil || (v != "true" && v != "false") {
			Error(w, http.StatusBadRequest, "done must be true or false")
			return
		}
		opts.Done = &b
	}
	if v := q.Get("limit"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil || n < 1 || n > maxLimit {
			Error(w, http.StatusBadRequest, "limit must be an integer from 1 to 100")
			return
		}
		opts.Limit = n
	}
	if v := q.Get("offset"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil || n < 0 {
			Error(w, http.StatusBadRequest, "offset must be an integer of 0 or more")
			return
		}
		opts.Offset = n
	}
	JSON(w, http.StatusOK, h.store.List(opts))
}
EOF
cat > cmd/server/main.go <<'EOF'
// Command server serves the todo API.
package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"example.com/app/internal/api"
	"example.com/app/internal/clock"
	"example.com/app/internal/log"
	"example.com/app/internal/todo"
)

const shutdownTimeout = 10 * time.Second

func main() {
	if err := run(os.Args[1:], os.Stdout, os.Stderr); err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		os.Exit(1)
	}
}

func run(args []string, stdout, stderr io.Writer) error {
	fs := flag.NewFlagSet("server", flag.ContinueOnError)
	fs.SetOutput(stderr)
	addr := fs.String("addr", ":8080", "address to listen on")
	if err := fs.Parse(args); err != nil {
		return fmt.Errorf("parse flags: %w", err)
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	return serve(ctx, *addr)
}

func serve(ctx context.Context, addr string) error {
	store := todo.NewStore(clock.Real{})
	srv := &http.Server{
		Addr:              addr,
		Handler:           api.NewHandler(store),
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	errc := make(chan error, 1)
	go func() { errc <- srv.ListenAndServe() }()
	log.Info("listening", "addr", addr)

	select {
	case err := <-errc:
		return fmt.Errorf("serve %s: %w", addr, err)
	case <-ctx.Done():
	}

	log.Info("shutting down")
	shutCtx, cancel := context.WithTimeout(context.Background(), shutdownTimeout)
	defer cancel()
	if err := srv.Shutdown(shutCtx); err != nil {
		return fmt.Errorf("shutdown: %w", err)
	}
	if err := <-errc; !errors.Is(err, http.ErrServerClosed) {
		return fmt.Errorf("serve %s: %w", addr, err)
	}
	return nil
}
EOF

